(async () => {
  const dir = (u) => new URL(u, location.href).pathname.replace(/\/?$/, '/');
  const pages = [...new Set([dir(location.href), ...[...document.querySelectorAll('.pagination a.page-link')]
    .map((a) => dir(a.getAttribute('href')))])];
  const cards = [];
  for (const p of pages) {
    const doc = new DOMParser().parseFromString(await (await fetch(p)).text(), 'text/html');
    for (const img of doc.querySelectorAll('img.card-img-top')) {
      const src = img.getAttribute('src') || '';
      const r = await fetch(new URL(src, location.origin + p), { method: 'HEAD' });
      const type = r.headers.get('content-type') || '';
      const why = [];
      if (src.replace(/^[a-z]+:\/\//i, '').includes('//')) why.push('double slash');
      if (!r.ok) why.push('HTTP ' + r.status);
      if (!type.startsWith('image/')) why.push('not an image (' + (type || 'no type') + ')');
      if (img.getAttribute('loading') !== 'lazy') why.push('not lazy');
      cards.push({ page: p, src, alt: img.getAttribute('alt'), status: r.status, type, broken: why.join(', ') || null });
    }
  }
  window.__cardImages = cards;
  return { pages, cards: cards.length, broken: cards.filter((c) => c.broken), all: cards };
})()

(() => {
  const loads = (c) => !/HTTP|image/.test(c.broken);
  const bad = (window.__cardImages || []).filter((c) => c.broken).sort((a, b) => loads(a) - loads(b));
  if (bad.length) throw new Error(bad.length + ' broken card image(s), ' + bad.filter((c) => !loads(c)).length
    + ' not loading: ' + bad.map((c) => c.page + ' ' + JSON.stringify(c.src) + ' ' + c.broken).join(' | '));
  return 0;
})()

